#include <cstdint>
#include <format>
#include <iostream>

namespace bench {

// Encoder ticks are an exact count, so they are an integer with a type of their own.
struct Ticks {
  std::int64_t count;
};

// One reading of both wheels, written {.left = {100}, .right = {300}} so the wheels can't be swapped.
struct WheelTicks {
  Ticks left;
  Ticks right;
};

// Measured once per robot.
struct Wheels {
  double metres_per_tick;
  double base_m;  // distance between the two wheels
};

// Distance driven by the middle of the axle: the mean of both wheels.
[[nodiscard]] double distance_m(WheelTicks ticks, const Wheels& wheels) {
  const std::int64_t both = ticks.left.count + ticks.right.count;
  return static_cast<double>(both) / 2.0 * wheels.metres_per_tick;
}

}  // namespace bench

int main() {
  constexpr bench::Wheels wheels{.metres_per_tick = 0.001, .base_m = 0.4};
  std::cout << std::format("{:.2f} m\n", bench::distance_m({.left = {1000}, .right = {1000}}, wheels));
}

#include <gtest/gtest.h>

#include "bench/odometry.hpp"

constexpr bench::Wheels wheels{.metres_per_tick = 0.001, .base_m = 0.4};

TEST(Distance, ZeroTicksIsZero) {
  EXPECT_EQ(bench::distance_m({.left = {0}, .right = {0}}, wheels), 0.0);
}

TEST(Distance, AveragesBothWheels) {
  EXPECT_NEAR(bench::distance_m({.left = {100}, .right = {300}}, wheels), 0.2, 1e-12);
}

#include <cmath>
#include <format>
#include <iostream>

#include "bench/odometry.hpp"

int main() {
  constexpr bench::Wheels wheels{.metres_per_tick = 0.001, .base_m = 0.4};
  const double got = bench::distance_m({.left = {100}, .right = {300}}, wheels);
  if (std::abs(got - 0.2) < 1e-12) return 0;
  std::cout << std::format("distance_m is {}, expected 0.2\n", got);
  return 1;
}

namespace bench {

double heading_change_rad(WheelTicks ticks, const Wheels& wheels) {
  const std::int64_t difference = ticks.right.count - ticks.left.count;  // exact
  return static_cast<double>(difference) * wheels.metres_per_tick / wheels.base_m;
}

}  // namespace bench

TEST(HeadingChange, EqualTicksIsZero) {
  EXPECT_EQ(bench::heading_change_rad({.left = {500}, .right = {500}}, wheels), 0.0);
}

TEST(HeadingChange, RightWheelFurtherTurnsLeft) {
  EXPECT_NEAR(bench::heading_change_rad({.left = {1000}, .right = {1100}}, wheels), 0.25, 1e-12);
}

TEST(HeadingChange, SwappingWheelsFlipsSign) {
  EXPECT_EQ(bench::heading_change_rad({.left = {1100}, .right = {1000}}, wheels),
            -bench::heading_change_rad({.left = {1000}, .right = {1100}}, wheels));
}

#include <cstdint>
#include <iostream>

namespace bench {
struct Ticks {
  std::int64_t count;
};
struct WheelTicks {
  Ticks left;
  Ticks right;
};
struct Wheels {
  double metres_per_tick;
  double base_m;
};

[[nodiscard]] double heading_change_rad(WheelTicks ticks, const Wheels& wheels) {
  const std::int64_t difference = ticks.right.count - ticks.left.count;
  return static_cast<double>(difference) * wheels.metres_per_tick / wheels.base_m;
}
}  // namespace bench

int main() {
  constexpr bench::Wheels wheels{.metres_per_tick = 0.001, .base_m = 0.4};
  const double left_turn = bench::heading_change_rad({.left = {1000}, .right = {1100}}, wheels);
  const double right_turn = bench::heading_change_rad({.left = {1100}, .right = {1000}}, wheels);
  std::cout << bench::heading_change_rad({.left = {500}, .right = {500}}, wheels) << ' ' << left_turn << ' ' << right_turn
            << ' ' << std::boolalpha << (right_turn == -left_turn) << '\n';
}
